import os
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

PAYMENT_KEYS = ("id", "amount_minor", "currency", "created_at", "status")


def serve(port: int, store, client) -> None:
    handler_cls = _make_handler(store, client)
    server = HTTPServer(("127.0.0.1", port), handler_cls)
    server.serve_forever()


def _make_handler(store, client):
    class Handler(BaseHTTPRequestHandler):
        def log_message(self, fmt, *args):
            pass  # silence default logging

        def _json_response(self, status: int, body: dict):
            data = json.dumps(body).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def _html_response(self, status: int, html_bytes: bytes):
            self.send_response(status)
            self.send_header("Content-Type", "text/html")
            self.send_header("Content-Length", str(len(html_bytes)))
            self.end_headers()
            self.wfile.write(html_bytes)

        def _read_body(self) -> bytes:
            length = int(self.headers.get("Content-Length", 0))
            return self.rfile.read(length) if length else b""

        def do_GET(self):
            parsed = urlparse(self.path)
            path = parsed.path
            qs = parse_qs(parsed.query)

            if path == "/":
                self._handle_root()
            elif path == "/api/health":
                self._handle_health()
            elif path == "/api/payments":
                self._handle_payments(qs)
            elif path == "/api/summary":
                self._handle_summary()
            else:
                self._json_response(404, {"error": "not_found"})

        def do_POST(self):
            parsed = urlparse(self.path)
            path = parsed.path

            if path == "/api/sync":
                self._read_body()  # consume body
                self._handle_sync()
            else:
                self._json_response(404, {"error": "not_found"})

        def _handle_root(self):
            html_path = os.path.join(
                os.path.dirname(__file__), "web", "index.html"
            )
            try:
                with open(html_path, "rb") as f:
                    self._html_response(200, f.read())
            except FileNotFoundError:
                self._json_response(404, {"error": "not_found"})

        def _handle_health(self):
            count = store.count()
            last_sync = store.last_sync()
            self._json_response(200, {
                "status": "ok",
                "payments": count,
                "last_sync": last_sync,
            })

        def _handle_payments(self, qs: dict):
            limit = 25
            offset = 0

            # Parse and validate limit
            if "limit" in qs:
                try:
                    limit = int(qs["limit"][0])
                    if limit < 0:
                        raise ValueError
                except (ValueError, TypeError):
                    self._json_response(400, {"error": "bad_request"})
                    return

            # Parse and validate offset
            if "offset" in qs:
                try:
                    offset = int(qs["offset"][0])
                    if offset < 0:
                        raise ValueError
                except (ValueError, TypeError):
                    self._json_response(400, {"error": "bad_request"})
                    return

            # Cap limit at 100
            if limit > 100:
                limit = 100

            all_payments = store.all_payments()
            total = len(all_payments)
            slice_start = offset
            slice_end = offset + limit
            data = [
                {k: p[k] for k in PAYMENT_KEYS}
                for p in all_payments[slice_start:slice_end]
            ]

            self._json_response(200, {
                "data": data,
                "total": total,
                "limit": limit,
                "offset": offset,
            })

        def _handle_summary(self):
            all_payments = store.all_payments()
            count = len(all_payments)

            if count == 0:
                self._json_response(200, {
                    "count": 0,
                    "total_minor": 0,
                    "currency": "EUR",
                    "oldest": None,
                    "newest": None,
                })
                return

            total_minor = sum(p["amount_minor"] for p in all_payments)
            # store.all_payments() is oldest-first
            oldest = all_payments[0]["created_at"]
            newest = all_payments[-1]["created_at"]

            self._json_response(200, {
                "count": count,
                "total_minor": total_minor,
                "currency": "EUR",
                "oldest": oldest,
                "newest": newest,
            })

        def _handle_sync(self):
            payments = client.fetch_all_payments()
            inserted = store.upsert_many(payments)
            store.set_last_sync()
            total = store.count()

            self._json_response(200, {
                "fetched": len(payments),
                "inserted": inserted,
                "total": total,
            })

    return Handler
